#define NOVA_TEST_LIBRARY 1
#include "Processor.h"
#include <iostream>
juce::AudioProcessorEditor* NovaProcessor::createEditor(){return nullptr;}
int main(int argc,char** argv){try{if(argc!=4)throw std::runtime_error("client endpoint wav token");juce::ScopedJuceInitialiser_GUI gui;NovaProcessor p;p.prepareToPlay(48000,512);auto pump=[](){juce::MessageManager::getInstance()->runDispatchLoopUntil(20);};p.loadSample(juce::File(argv[2]));while(p.loading.load())pump();if(!p.hasReference())throw std::runtime_error("reference failed");p.selectRange({0,p.sourceView()->duration});p.configureRemote(argv[1],argv[3]);p.remoteEnabled.store(true);if(!p.startFit())throw std::runtime_error(p.status().toStdString());auto end=juce::Time::getMillisecondCounterHiRes()+185000;while(p.fitting.load()&&juce::Time::getMillisecondCounterHiRes()<end)pump();if(p.fitting.load()||p.program.load()!=-1||p.alternativeNames().isEmpty())throw std::runtime_error(p.status().toStdString());if(p.v("fine")!=0)throw std::runtime_error("remote pitch not centred");juce::MemoryBlock state;p.getStateInformation(state);auto xml=juce::AudioProcessor::getXmlFromBinary(state.getData(),static_cast<int>(state.getSize()));if(xml->toString().contains(argv[3])||xml->toString().contains(argv[1]))throw std::runtime_error("credentials serialized");p.undoFit();if(p.program.load()<0)throw std::runtime_error("remote undo failed");std::cout<<"PASS: actual plugin client -> HTTP -> worker -> validated editable synthesis; undo and credentials\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
